package com.mfg.plm.workflow;import com.mfg.plm.service.EngineeringChangeChainService;import com.mfg.workflow.callback.ApprovalCallback;import com.mfg.workflow.entity.WfInstance;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;@Component @RequiredArgsConstructor public class EcoApprovalCallback implements ApprovalCallback{private final EngineeringChangeChainService service;public boolean supports(String type){return "ECO".equals(type);}public void onApproved(WfInstance i){service.approvedEco(i.getBizId());}public void onRejected(WfInstance i,String reason){service.rejectedEco(i.getBizId());}}
